INSERT INTO `uwsaccounting_invoice` (`invoice_id`, `invoice_number`, `invoice_date`, `customer_id`, `product_name`, `quantity`, `unit`, `hsn_code`, `gst`, `sgst`, `cgst`, `igst`, `gst_type`, `price`, `amount`, `description`, `uid`, `discount`) VALUES
(255, 'UWS/INV/2627/055', '2026-04-29', 912, 'D1001', 0.25, 'SET', '12345432', '18%', 689.06, 689.06, 0, 'S', 35000, 7656.25, '<p>Dosing SystemDosing SystemDosing SystemDosing SystemDosing SystemDosing System<br />\r\n<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p>ble Data Type Fix</p>\r\n\r\n<p>Here&#39;s an improved version of your code that handles double/decimal data types properly and fixes several issues:</p>\r\n\r\n<p>javascript</p>\r\n\r\n<pre>\r\n$(document).on(&quot;keyup&quot;, &quot;.discount_auto&quot;, function(e) {\r\n    // Get discount element ID\r\n    var discount_id = $(this).attr(&quot;id&quot;);\r\n    var disc_id = discount_id.split(&quot;unt&quot;);\r\n    \r\n    // Get amount values as float (double)\r\n    var amount = parseFloat($(&quot;#amount&quot; + disc_id[1]).val()) || 0;\r\n    var amount_temp = parseFloat($(&quot;#amount_temp&quot; + disc_id[1]).val()) || 0;\r\n    \r\n    // Update amount display with 2 decimal places\r\n    $(&quot;#span_amount&quot; + disc_id[1]).text(amount_temp.toFixed(2));\r\n    $(&quot;#amount&quot; + disc_id[1]).val(amount_temp.toFixed(2));\r\n    \r\n    // Get discount and quantity as float\r\n    var discount = $(this).val();\r\n    var quantity = parseFloat($(&quot;#quantity&quot; + disc_id[1]).val()) || 0;\r\n    \r\n    // Check GST type\r\n    var gst_discount_check = $(&quot;#gst_discount_check&quot;).val();\r\n    var quotation_igst_check = $(&quot;#quotation_igst_check&quot;).val();\r\n    \r\n    // Parse discount as float (double)\r\n    var discount_float = parseFloat(discount) || 0;\r\n    \r\n    // Validate discount percentage (allow up to 100 with decimals)\r\n    if (discount_float &gt; 100) {\r\n        $(&quot;#discount&quot; + disc_id[1]).val(&quot;0&quot;);\r\n        alert(&quot;Oops!! Discount cannot be more than 100%&quot;);\r\n        $(this).val(&quot;0&quot;);\r\n        return false;\r\n    }\r\n    \r\n    // Validate negative discount\r\n    if (discount_float &lt; 0) {\r\n        $(&quot;#discount&quot; + disc_id[1]).val(&quot;0&quot;);\r\n        alert(&quot;Oops!! Discount cannot be negative&quot;);\r\n        $(this).val(&quot;0&quot;);\r\n        return false;\r\n    }\r\n    \r\n    // Calculate discount based on GST type\r\n    var discount_total = 0;\r\n    var base_amount = amount_temp;\r\n    \r\n    if (gst_discount_check || quotation_igst_check) {\r\n        // For GST/IGST cases, amount_temp is already the total\r\n        discount_total = base_amount - (base_amount * discount_float / 100);\r\n        \r\n        if (gst_discount_check) {\r\n            var gst_per = $(&quot;#gst_per&quot; + disc_id[1]).val();\r\n            var split_gst_per = parseFloat(gst_per.split(&quot;%&quot;)[0]) || 0;\r\n            \r\n            // Calculate GST on discounted amount\r\n            var gst_amount = discount_total * split_gst_per / 100;\r\n            var cgst_amount = gst_amount / 2;\r\n            \r\n            $(&quot;#sgst&quot; + disc_id[1]).val(cgst_amount.toFixed(2));\r\n            $(&quot;#cgst&quot; + disc_id[1]).val(cgst_amount.toFixed(2));\r\n            \r\n        } else if (quotation_igst_check) {\r\n            var gst_per = $(&quot;#gst_per&quot; + disc_id[1]).val();\r\n            var split_gst_per = parseFloat(gst_per.split(&quot;%&quot;)[0]) || 0;\r\n            \r\n            var igst_amount = discount_total * split_gst_per / 100;\r\n            $(&quot;#igst&quot; + disc_id[1]).val(igst_amount.toFixed(2));\r\n        }\r\n        \r\n    } else {\r\n        // No GST: multiply by quantity\r\n        base_amount = amount_temp * quantity;\r\n        discount_total = base_amount - (base_amount * discount_float / 100);\r\n    }\r\n    \r\n    // Apply discount calculation\r\n    if (discount_float === 0 || isNaN(discount_float) || discount === &quot;&quot;) {\r\n        var amount_assigned = base_amount;\r\n        $(&quot;#amount&quot; + disc_id[1]).val(amount_assigned.toFixed(2));\r\n        $(&quot;#amount_temp&quot; + disc_id[1]).val(amount_assigned.toFixed(2));\r\n        $(&quot;#span_amount&quot; + disc_id[1]).text(amount_assigned.toFixed(2));\r\n    } else {\r\n        $(&quot;#span_amount&quot; + disc_id[1]).text(discount_total.toFixed(2));\r\n        $(&quot;#amount&quot; + disc_id[1]).val(discount_total.toFixed(2));\r\n    }\r\n    \r\n    // Calculate total sum\r\n    if (typeof calculateSum1 === &#39;function&#39;) {\r\n        calculateSum1();\r\n    }\r\n});\r\n\r\n// Separate keypress validation for discount inputs\r\n$(document).on(&quot;keypress&quot;, &quot;.discount_auto&quot;, function(e) {\r\n    var charCode = e.which;\r\n    var currentValue = $(this).val();\r\n    \r\n    // Allow: backspace(8), delete(46), tab(9), escape(27), enter(13)\r\n    if (charCode === 8 || charCode === 0 || charCode === 9 || charCode === 27 || charCode === 13) {\r\n        return true;\r\n    }\r\n    \r\n    // Allow decimal point\r\n    if (charCode === 46) {\r\n        // Prevent multiple decimal points\r\n        if (currentValue.indexOf(&#39;.&#39;) !== -1) {\r\n            e.preventDefault();\r\n            alert(&quot;Oops!! Only one decimal point allowed&quot;);\r\n            return false;\r\n        }\r\n        return true;\r\n    }\r\n    \r\n    // Allow numbers\r\n    if (charCode &gt;= 48 &amp;&amp; charCode &lt;= 57) {\r\n        return true;\r\n    }\r\n    \r\n    // Block all other characters\r\n    e.preventDefault();\r\n    alert(&quot;Oops!! Please Enter Number Only (use decimal point for percentage)&quot;);\r\n    $(this).val(&quot;&quot;);\r\n    return false;\r\n});\r\n\r\n// Helper function to safely parse float with 2 decimal precision\r\nfunction parseFloatWithPrecision(value, decimals = 2) {\r\n    var parsed = parseFloat(value);\r\n    if (isNaN(parsed)) return 0;\r\n    return parseFloat(parsed.toFixed(decimals));\r\n}\r\n\r\n// Helper function to round to 2 decimal places\r\nfunction roundToTwoDecimals(value) {\r\n    return Math.round((value + Number.EPSILON) * 100) / 100;\r\n}</pre>\r\n\r\n<h2>Key Improvements:</h2>\r\n\r\n<ol>\r\n	<li>\r\n	<p><strong>Proper Double/Float Parsing</strong>: Uses&nbsp;<code>parseFloat()</code>&nbsp;with fallback to 0 for all numeric values</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Fixed Decimal Precision</strong>: All monetary values displayed with&nbsp;<code>.toFixed(2)</code></p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Separated Validation</strong>: Moved keypress validation to separate event handler to prevent multiple bindings</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Fixed Calculation Logic</strong>:</p>\r\n\r\n	<ul>\r\n		<li>\r\n		<p>Corrected the discount calculation formula</p>\r\n		</li>\r\n		<li>\r\n		<p>Properly handles GST calculations with discounted amount</p>\r\n		</li>\r\n	</ul>\r\n	</li>\r\n	<li>\r\n	<p><strong>Added Negative Discount Validation</strong>: Prevents negative discount values</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Improved Rounding</strong>: Uses proper rounding for monetary values</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Added Helper Functions</strong>: For consistent number parsing and rounding</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Safe Function Call</strong>: Checks if&nbsp;<code>calculateSum1</code>&nbsp;exists before calling</p>\r\n	</li>\r\n</ol>\r\n\r\n<h2>Usage with Double Data Types:</h2>\r\n\r\n<p>For server-side handling (PHP example):</p>\r\n\r\n<p>php</p>\r\n\r\n<pre>\r\n// When saving to database\r\n$discount = (double) $_POST[&#39;discount&#39;];\r\n$amount = (double) $_POST[&#39;amount&#39;];\r\n\r\n// Store as DECIMAL(10,2) in MySQL\r\n// UPDATE table SET discount = :discount, amount = :amount WHERE id = :id</pre>\r\n\r\n<p>For JavaScript data exchange:</p>\r\n\r\n<p>javascript</p>\r\n\r\n<pre>\r\n// Parse JSON responses with double values\r\n$.getJSON(&#39;/api/get-data&#39;, function(response) {\r\n    var discountValue = parseFloat(response.discount) || 0;\r\n    var amountValue = parseFloat(response.amount) || 0;\r\n});</pre>\r\n\r\n<p>This ensures all decimal values are properly handled as double/float data types throughout your application.</p>\r\n\r\n<p>give me the changes and code</p>\r\n\r\n<p>Here are the specific changes and the complete corrected code:</p>\r\n\r\n<h2>Key Changes Made:</h2>\r\n\r\n<ol>\r\n	<li>\r\n	<p><strong>Fixed nested event binding</strong>&nbsp;- Moved keypress validation outside the keyup handler</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Added proper float parsing</strong>&nbsp;with fallback to 0</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Fixed discount calculation formula</strong>&nbsp;- from&nbsp;<code>(total / 100) * discount</code>&nbsp;to&nbsp;<code>total * (discount / 100)</code></p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Added negative discount validation</strong></p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Fixed GST calculation order</strong>&nbsp;- Apply discount first, then calculate GST</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Added proper rounding to 2 decimal places</strong></p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Removed duplicate code</strong>&nbsp;inside discount calculation</p>\r\n	</li>\r\n</ol>\r\n\r\n<h2>Complete Corrected Code:</h2>\r\n\r\n<p>javascript</p>\r\n\r\n<pre>\r\n// Keyup event for discount calculation\r\n$(document).on(&quot;keyup&quot;, &quot;.discount_auto&quot;, function() {\r\n    // Get discount element ID\r\n    var discount_id = $(this).attr(&quot;id&quot;);\r\n    var disc_id = discount_id.split(&quot;unt&quot;);\r\n    \r\n    // Get amount values as float\r\n    var amount_temp = parseFloat($(&quot;#amount_temp&quot; + disc_id[1]).val()) || 0;\r\n    \r\n    // Update amount display\r\n    $(&quot;#span_amount&quot; + disc_id[1]).text(amount_temp.toFixed(2));\r\n    $(&quot;#amount&quot; + disc_id[1]).val(amount_temp.toFixed(2));\r\n    \r\n    // Get discount and quantity as float\r\n    var discount = $(this).val();\r\n    var discount_float = parseFloat(discount) || 0;\r\n    var quantity = parseFloat($(&quot;#quantity&quot; + disc_id[1]).val()) || 0;\r\n    \r\n    // Check GST type\r\n    var gst_discount_check = $(&quot;#gst_discount_check&quot;).val();\r\n    var quotation_igst_check = $(&quot;#quotation_igst_check&quot;).val();\r\n    \r\n    // Validate discount percentage\r\n    if (discount_float &gt; 100) {\r\n        $(&quot;#discount&quot; + disc_id[1]).val(&quot;0&quot;);\r\n        $(this).val(&quot;0&quot;);\r\n        alert(&quot;Oops!! Discount is not more than 100%&quot;);\r\n        return false;\r\n    }\r\n    \r\n    // Validate negative discount\r\n    if (discount_float &lt; 0) {\r\n        $(&quot;#discount&quot; + disc_id[1]).val(&quot;0&quot;);\r\n        $(this).val(&quot;0&quot;);\r\n        alert(&quot;Oops!! Discount cannot be negative&quot;);\r\n        return false;\r\n    }\r\n    \r\n    // Calculate total amount before discount\r\n    var total_amount = amount_temp;\r\n    \r\n    // For non-GST case, multiply by quantity\r\n    if (!gst_discount_check &amp;&amp; !quotation_igst_check) {\r\n        total_amount = amount_temp * quantity;\r\n    }\r\n    \r\n    // Calculate discount amount\r\n    var discount_amount = total_amount * (discount_float / 100);\r\n    var discount_total = total_amount - discount_amount;\r\n    \r\n    // Handle GST calculations\r\n    if (gst_discount_check) {\r\n        var gst_per = $(&quot;#gst_per&quot; + disc_id[1]).val();\r\n        var split_gst_per = parseFloat(gst_per.split(&quot;%&quot;)[0]) || 0;\r\n        \r\n        var gst_amount = discount_total * (split_gst_per / 100);\r\n        var cgst_amount = gst_amount / 2;\r\n        \r\n        $(&quot;#sgst&quot; + disc_id[1]).val(cgst_amount.toFixed(2));\r\n        $(&quot;#cgst&quot; + disc_id[1]).val(cgst_amount.toFixed(2));\r\n        \r\n    } else if (quotation_igst_check) {\r\n        var gst_per = $(&quot;#gst_per&quot; + disc_id[1]).val();\r\n        var split_gst_per = parseFloat(gst_per.split(&quot;%&quot;)[0]) || 0;\r\n        \r\n        var igst_amount = discount_total * (split_gst_per / 100);\r\n        $(&quot;#igst&quot; + disc_id[1]).val(igst_amount.toFixed(2));\r\n    }\r\n    \r\n    // Apply discount calculation to display\r\n    if (discount_float == 0 || discount == &quot;&quot; || isNaN(discount_float)) {\r\n        $(&quot;#amount&quot; + disc_id[1]).val(total_amount.toFixed(2));\r\n        $(&quot;#span_amount&quot; + disc_id[1]).text(total_amount.toFixed(2));\r\n    } else {\r\n        $(&quot;#span_amount&quot; + disc_id[1]).text(discount_total.toFixed(2));\r\n        $(&quot;#amount&quot; + disc_id[1]).val(discount_total.toFixed(2));\r\n    }\r\n    \r\n    // Calculate total sum\r\n    calculateSum1();\r\n});\r\n\r\n// Keypress validation for discount inputs (moved outside keyup)\r\n$(document).on(&quot;keypress&quot;, &quot;.discount_auto&quot;, function(e) {\r\n    var charCode = e.which;\r\n    var currentValue = $(this).val();\r\n    \r\n    // Allow control keys\r\n    if (charCode == 8 || charCode == 0 || charCode == 9 || charCode == 27 || charCode == 13) {\r\n        return true;\r\n    }\r\n    \r\n    // Allow decimal point\r\n    if (charCode == 46) {\r\n        // Prevent multiple decimal points\r\n        if (currentValue.indexOf(&#39;.&#39;) != -1) {\r\n            alert(&quot;Oops!! Only one decimal point allowed&quot;);\r\n            e.preventDefault();\r\n            return false;\r\n        }\r\n        return true;\r\n    }\r\n    \r\n    // Allow numbers\r\n    if (charCode &gt;= 48 &amp;&amp; charCode &lt;= 57) {\r\n        return true;\r\n    }\r\n    \r\n    // Block all other characters\r\n    alert(&quot;Oops!! Please Enter Number Only (use decimal point for percentage)&quot;);\r\n    e.preventDefault();\r\n    $(this).val(&quot;&quot;);\r\n    return false;\r\n});</pre>\r\n\r\n<h2>Summary of Changes:</h2>\r\n\r\n<table>\r\n	<thead>\r\n		<tr>\r\n			<th>Issue</th>\r\n			<th>Original Code</th>\r\n			<th>Fixed Code</th>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td>Nested event binding</td>\r\n			<td><code>$(&quot;.discount_auto&quot;).keypress()</code>&nbsp;inside keyup</td>\r\n			<td>Separate&nbsp;<code>$(document).on(&quot;keypress&quot;)</code></td>\r\n		</tr>\r\n		<tr>\r\n			<td>Parse float</td>\r\n			<td>Missing&nbsp;<code>parseFloat()</code></td>\r\n			<td>Added&nbsp;<code>parseFloat() || 0</code></td>\r\n		</tr>\r\n		<tr>\r\n			<td>Discount formula</td>\r\n			<td><code>(total/100)*discount</code></td>\r\n			<td><code>total*(discount/100)</code></td>\r\n		</tr>\r\n		<tr>\r\n			<td>Negative discount</td>\r\n			<td>Not validated</td>\r\n			<td>Added validation</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Decimal rounding</td>\r\n			<td>Inconsistent</td>\r\n			<td>Added&nbsp;<code>.toFixed(2)</code>&nbsp;everywhere</td>\r\n		</tr>\r\n		<tr>\r\n			<td>GST calculation order</td>\r\n			<td>Before discount</td>\r\n			<td>After discount</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Empty value handling</td>\r\n			<td>Not handled</td>\r\n			<td>Added fallback to 0</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p>This code properly handles double/decimal values and ensures all calculations are accurate with 2 decimal places.</p>\r\n', 1, 12.5),
