INSERT INTO `uwsaccounting_settings` (`setting_id`, `company_logo`, `quotation_subheading`, `quotation_title`, `quotation_footer`, `quotation_memo`, `invoice_default_payment_term`, `invoice_title`, `invoice_subheading`, `invoice_footer`, `invoice_memo`, `invoice_notes`, `address`, `state_code`, `company_name`, `company_gst`, `company_pan`, `notes`, `po_title`, `po_subheading`, `po_footer`, `po_memo`, `po_note`, `mobile`, `email`, `uid`, `terms_and_conditions`, `payment_terms`, `process_schedule`, `taxes`, `exclusions`, `po_terms_and_conditions`, `po_payment_terms`, `po_process_schedule`, `po_taxes`, `po_exclusions`, `cin`, `company_stamp`, `purchase_requisition_notes`, `proforma_title`, `proforma_subheading`, `proforma_footer`, `proforma_memo`, `proforma_note`, `proforma_terms_and_conditions`, `proforma_payment_terms`, `proforma_process_schedule`, `proforma_taxes`, `proforma_exclusions`, `so_title`, `so_subheading`, `so_footer`, `so_memo`, `so_note`, `so_terms_and_conditions`, `so_payment_terms`, `so_process_schedule`, `so_taxes`, `so_exclusions`, `invoice_terms_and_conditions`, `invoice_payment_terms`, `invoice_process_schedule`, `invoice_taxes`, `invoice_exclusions`, `dc_title`, `dc_subheading`, `dc_footer`, `dc_memo`, `dc_note`, `dc_terms_and_conditions`, `dc_payment_terms`, `dc_process_schedule`, `dc_taxes`, `dc_exclusions`, `pv_title`, `pv_subheading`, `pv_footer`, `pv_memo`, `pv_note`, `pv_terms_and_conditions`, `pv_payment_terms`, `pv_process_schedule`, `pv_taxes`, `pv_exclusions`) VALUES
(1, './uploads/UWS_LOGO.png', 'Default subheading Quotation', 'Default title Quotation', 'Arcon Partition', '<p>Standard memo for quotation&nbsp;</p>\r\n', '1', '', '', '         VARSITY INDUSTRIAL PARK\r\nGAT NO. 462/2, VILLAGE NIGHOJE,\r\nNEAR MAHINDRA GATE NO. 8,\r\nTAL-KH', '1. Scope of requirement may change application cost will be change in future.\r\n\r\n2. Payment Terms\r\n-Advance 70% required before work start.\r\n\r\n3. GST Number: 27AAACX1482C1ZJ', 'Payment by: Cheque or Online Transfer Company Bank Account Details for\r\nOnline Transfer Name: Xform Technologies Private Limited Account No: 0668102000008075\r\nIFSC Code: IBKL0000668\r\nAccount Type: Current Account\r\nBranch: IDBI Bank, S. N. 39/3, Siddheshwar, Tingre Nagar Road, Pune-411015\r\nCheque will be drawn “Xform Technologies Private Limited” and sent to our company address', 'Plot No.19/C, Block D-1,\r\nHeuu Industrial Spaces, Shop No.342,\r\n3rd Floor, MIDC Chinchwad\r\nPUNE - 411019.', '27', 'Xformtech', '27AAACX1482C1ZJ', 'AAACX1482C', '<p>Notes for new quotation&nbsp;</p>\r\n', 'Default title Purchase Order', ' Default subheading Purchase Order', 'Default footer  Purchase Order                                                  ', ' Standard memo Purchase Order', '<p>Note&nbsp;&nbsp;Purchase Order</p>\r\n', '9890726453', 'contact@xform.in', 1, '<p><strong>Transportation</strong></p>\r\n\r\n<ol>\r\n	<li>Cost of transportation from our warehouse to your designated warehouse or project site is payable extra and is not included in quoted price (unless specified)</li>\r\n</ol>\r\n\r\n<p><strong>Packaging</strong></p>\r\n\r\n<ol>\r\n	<li>Cost of normal packaging in corrugated carton/wrapping is included in quoted price but does not cover cost of wooden crating, palletisation, weather proof packing or any other special packing or fumigation charges.</li>\r\n</ol>\r\n\r\n<p><strong>Loading/Unloading/Handling</strong></p>\r\n\r\n<ol>\r\n	<li>Cost of one time loading in our warehouse is included in quoted price cost of unloading at your designated warehouse or project site is not included in quoted price.</li>\r\n	<li>In case of unloading is included and specifically mentioned in our quote, it shall be only at ground floor level nearest to the entrance.</li>\r\n</ol>\r\n\r\n<p><strong>Unloading by Mathadi</strong></p>\r\n\r\n<ol>\r\n	<li>Unloading by local mathadi/or any labor union member is at your cost and risk, we shall not interact/engage in any dealing with them of any kind for loading and handling of goods.</li>\r\n</ol>\r\n', '<ol>\r\n	<li>&nbsp;50% ADVANCE,40% BEFOR GLASS,10% AFTER COMPLETION (INCLUDING GST AMOUNT)</li>\r\n	<li>&nbsp;Payment shall be in favour of &quot;ARCON PARTITION&quot;</li>\r\n	<li>&nbsp;There is No retention on behalf of &quot;ARCON PARTITION&quot;</li>\r\n</ol>\r\n\r\n<p><strong>Delay in project schedule</strong></p>\r\n\r\n<ol>\r\n	<li>&nbsp;On changing of approved specification by the client</li>\r\n	<li>&nbsp;On delay in approval of samples,</li>\r\n	<li>&nbsp;On non-receipt of payment in scheduled time by the client</li>\r\n	<li>&nbsp;On noncompliance of site handover or any local authority or legal approval</li>\r\n	<li>&nbsp;Due to natural calamity, strike, traffic problem not attributed to system installer</li>\r\n</ol>\r\n', '<p><strong>Installation</strong></p>\r\n\r\n<ol>\r\n	<li>&nbsp;Installation unless specifically mentioned in this offer, is not in our scope and is not included in&nbsp; &nbsp;the quoted price</li>\r\n	<li>&nbsp;Where installation is part of our scope same shall be specifically mentioned in our office and&nbsp; &nbsp;such installation shall not include any types of civil work whatsoever in our civil works, if any&nbsp; &nbsp;shall be scope of customer.</li>\r\n	<li>&nbsp;Arcon&nbsp;partition system work will start only after clearance of full site, means no part work will be done, once started Arcon partition system will finish in single trough.</li>\r\n	<li>&nbsp;Any changing in drawing or verbal communication at site will not be accepted until it is done on mail along with designated person only.</li>\r\n	<li>&nbsp;We are taking glass pannel width in partition upto 1200 mm only,if changes in above width&nbsp; &nbsp;required at site than inform us before glass measurment,if any additional cost arise from this will not be paid by us</li>\r\n	<li>GLASS WILL BE HAVING BEND UPTO 1MM TO 6MM PER MTR</li>\r\n	<li>&nbsp;INSTALLATION SCHEDULE IS SUBJECT TO PAYMENT</li>\r\n	<li>Delivery Schedule : 15 days after receiving PO and advance</li>\r\n	<li>Validity of Quotation: 15 Days from the date of this quotation</li>\r\n</ol>\r\n', '<ol>\r\n	<li>&nbsp;Gst is payable extra as actual, if not included in quote</li>\r\n	<li>&nbsp;Any other levies and taxes, if any as mandated by the statuary authorities from time to time, at time of placing of order shall be payable extra, and is not included in quoted price (unless specified)</li>\r\n</ol>\r\n', '<p><strong>Security for physical material</strong></p>\r\n\r\n<ol>\r\n	<li>It is the responsibility of the client for security of physical material lying at site. The liability from our side ceases as soon as the acknowledged of receipt of physical material duly signed by authorized representative of client. Once the duly acknowledged received at site will not be returnable under any circumstances</li>\r\n</ol>\r\n\r\n<p><strong>Jurisdiction</strong></p>\r\n\r\n<ol>\r\n	<li>All disputes shall be subject to Mumbai jurisdiction only</li>\r\n</ol>\r\n', '<p>Terms &amp; Conditions&nbsp;&nbsp;Purchase Order</p>\r\n', '<p>&nbsp;</p>\r\n\r\n<p>Payment Terms&nbsp;&nbsp;Purchase Order</p>\r\n', '<p>&nbsp;</p>\r\n\r\n<p>Process Schedule&nbsp;&nbsp;Purchase Order</p>\r\n', '<p>&nbsp;</p>\r\n\r\n<p>Taxes&nbsp;&nbsp;Purchase Order</p>\r\n', '<p>Exclusions&nbsp;&nbsp;Purchase Order</p>\r\n', 'U72500PN2013PTC149350', './uploads/londhe_sign.jpg', 'All purchases must comply with the specifications mentioned in the requisition. Prices are exclusive of applicable taxes unless otherwise stated. Suppliers are required to ensure proper packaging and timely delivery of goods. Any deviations from the requisition must be approved in writing by the procurement department. Partial deliveries may be accepted only with prior consent. Invoices must reference the Purchase Requisition number for proper processing. Warranty, after-sales service, and any relevant certifications should accompany the delivery. Discrepancies, damages, or shortages must be reported immediately to the requesting department to facilitate resolution. For urgent items, suppliers are expected to coordinate delivery directly with the designated requestor.', ' Default title Proforma Invoice', ' Default subheading Proforma Invoice', 'Default footer Proforma Invoice', '<p>Standard memo&nbsp;Proforma Invoice</p>\r\n', '<p>Note&nbsp;Proforma Invoice</p>\r\n', '<p>Terms &amp; Conditions for PI</p>\r\n', '<p>Payment Terms for PI</p>\r\n', '<p>Process Schedule for pi</p>\r\n', '<p>&nbsp;</p>\r\n\r\n<p>Taxes for pi</p>\r\n', '<p>&nbsp;</p>\r\n\r\n<p>Exclusions for pi</p>\r\n', ' Default title so', 'Default subheading so', ' Default footer so', '<p>&nbsp;</p>\r\n\r\n<p>Standard memo so</p>\r\n', '<p>&nbsp;</p>\r\n\r\n<p>Note so</p>\r\n', '<p>Terms and conditions for so</p>\r\n', '<p>&nbsp;</p>\r\n\r\n<p>Payment Terms so</p>\r\n', '<p>&nbsp;</p>\r\n\r\n<p>Process Schedule so</p>\r\n', '<p>&nbsp;</p>\r\n\r\n<p>Taxes so</p>\r\n', '<p>&nbsp;</p>\r\n\r\n<p>Exclusions so</p>\r\n', '<p>Terms and conditions for invoice</p>\r\n', '<p>payment terms&nbsp; for invoice</p>\r\n', '<p>process schedule for invoice</p>\r\n', '<p>taxes&nbsp; for invoice</p>\r\n', '<p>Exclusion for invoice</p>\r\n', 'Title Delivery Challan', 'Subheading Delivery Challan', '<p>ghjfykgulhi</p>\r\n', '<p>utrheghjkl</p>\r\n', '<p>djtrshehrjtfykguhi/j</p>\r\n', '<p>odzsacAVDFXGNHLJK</p>\r\n', '<p>LUGKYTRHSEFDZXGCHJVGKI</p>\r\n', '<p>ETSHXGFYGOR6KFYGU;YTILF.H;GULKIH;GOU</p>\r\n', '<p>KDHFZDXGJHVBK.L/J</p>\r\n', '<p>KLJHXGFZGDHXRGTJKULI;OHJ</p>\r\n', 'Title Purchase Voucher', 'Subheading Purchase Voucher', '<p>&nbsp;</p>\r\n\r\n<p>Footer&nbsp;Purchase Voucher</p>\r\n', '<p>Memo&nbsp;Purchase Voucher</p>\r\n', '<p>&nbsp;</p>\r\n\r\n<p>Note&nbsp;Purchase Voucher</p>\r\n', '<p>&nbsp;</p>\r\n\r\n<p>Terms &amp; Conditions&nbsp;Purchase Voucher</p>\r\n', '<p>&nbsp;</p>\r\n\r\n<p>Payment Terms&nbsp;Purchase Voucher</p>\r\n', '<p>&nbsp;</p>\r\n\r\n<p>Process Schedule&nbsp;Purchase Voucher</p>\r\n', '<p>&nbsp;</p>\r\n\r\n<p>Taxes&nbsp;Purchase Voucher</p>\r\n', '<p>&nbsp;</p>\r\n\r\n<p>Exclusions&nbsp;Purchase Voucher</p>\r\n');
